// Parse Telegram message and extract command
const message = $input.item.json.message;

let command = '';
let parameters = [];

if (message.text) {
  const parts = message.text.trim().split(/\s+/);
  command = parts[0].toLowerCase();
  parameters = parts.slice(1);
}

return {
  json: {
    chatId: message.chat.id.toString(),
    userId: message.from.id.toString(),
    userName: message.from.first_name + (message.from.last_name ? ' ' + message.from.last_name : ''),
    command: command,
    parameters: parameters,
    messageText: message.text,
    timestamp: new Date().toISOString()
  }
};

// Merge command with hotel context
const cmd = $('Parse Command').item.json;
const hotel = $input.item.json;

if (!hotel || !hotel.id) {
  return {
    json: {
      ...cmd,
      hotelId: null,
      hotelName: null,
      isAuthorized: false,
      errorMessage: 'You are not authorized to access hotel statistics. Please contact your administrator.'
    }
  };
}

return {
  json: {
    ...cmd,
    hotelId: hotel.id,
    hotelName: hotel.name,
    isAuthorized: true
  }
};

// Format today's statistics for Telegram
const context = $('Merge Context').item.json;
const stats = $input.item.json;

const total = (stats.ai_handled || 0) + (stats.human_handled || 0);
const aiRate = total > 0 ? ((stats.ai_handled / total) * 100).toFixed(1) : '0';

// Parse languages
let languages = stats.languages;
if (typeof languages === 'string') {
  try { languages = JSON.parse(languages); } catch(e) { languages = {}; }
}

// Parse top intents
let topIntents = stats.top_intents;
if (typeof topIntents === 'string') {
  try { topIntents = JSON.parse(topIntents); } catch(e) { topIntents = {}; }
}

const intentsList = Object.entries(topIntents || {})
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([intent, count]) => `  • ${intent}: ${count}`)
  .join('\n') || '  No data yet';

const message = `📊 *Today's Statistics*
🏨 ${context.hotelName}
📅 ${new Date().toLocaleDateString()}

*WhatsApp Messages*
📥 Received: ${stats.whatsapp_messages || 0}
📤 Sent: ${stats.whatsapp_responses || 0}

*Phone Calls*
📞 Received: ${stats.phone_calls || 0}

*Handling Performance*
🤖 AI Handled: ${stats.ai_handled || 0}
👤 Human Handled: ${stats.human_handled || 0}
📈 AI Success Rate: ${aiRate}%
🔄 Total Handoffs: ${stats.total_handoffs || 0}

*Languages*
🇦🇱 Albanian: ${languages.sq || 0}
🇬🇧 English: ${languages.en || 0}
🇮🇹 Italian: ${languages.it || 0}

*Top Intents*
${intentsList}`;

return {
  json: {
    ...context,
    statsMessage: message
  }
};

// Format week statistics
const context = $('Merge Context').item.json;
const stats = $input.item.json;

const total = (stats.ai_handled || 0) + (stats.human_handled || 0);
const aiRate = total > 0 ? ((stats.ai_handled / total) * 100).toFixed(1) : '0';
const avgResponseSec = stats.avg_response_time ? (stats.avg_response_time / 1000).toFixed(1) : 'N/A';

const message = `📊 *This Week's Statistics*
🏨 ${context.hotelName}
📅 Last 7 Days

*Communication Volume*
💬 WhatsApp Messages: ${stats.whatsapp_messages || 0}
📞 Phone Calls: ${stats.phone_calls || 0}
📈 Total Interactions: ${(stats.whatsapp_messages || 0) + (stats.phone_calls || 0)}

*Handling Performance*
🤖 AI Handled: ${stats.ai_handled || 0}
👤 Human Handled: ${stats.human_handled || 0}
📈 AI Success Rate: ${aiRate}%
🔄 Total Handoffs: ${stats.total_handoffs || 0}

*Response Time*
⏱ Avg Response: ${avgResponseSec}s

*Coverage*
📆 Days with activity: ${stats.days_with_data || 0}/7`;

return {
  json: {
    ...context,
    statsMessage: message
  }
};

// Format month statistics with breakdown
const context = $('Merge Context').item.json;
const stats = $input.item.json;

const total = (stats.ai_handled || 0) + (stats.human_handled || 0);
const aiRate = total > 0 ? ((stats.ai_handled / total) * 100).toFixed(1) : '0';
const avgResponseSec = stats.avg_response_time ? (stats.avg_response_time / 1000).toFixed(1) : 'N/A';

const monthName = new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

const message = `📊 *Monthly Statistics*
🏨 ${context.hotelName}
📅 ${monthName}

*Communication Volume*
💬 WhatsApp Messages: ${stats.whatsapp_messages || 0}
📞 Phone Calls: ${stats.phone_calls || 0}
📈 Total Interactions: ${(stats.whatsapp_messages || 0) + (stats.phone_calls || 0)}

*Handling Performance*
🤖 AI Handled: ${stats.ai_handled || 0}
👤 Human Handled: ${stats.human_handled || 0}
📈 AI Success Rate: ${aiRate}%

*Handoff Breakdown*
🔄 Total Handoffs: ${stats.total_handoffs || 0}
  • Low Confidence: ${stats.handoffs_confidence || 0}
  • Complex Request: ${stats.handoffs_complex || 0}
  • User Requested: ${stats.handoffs_user || 0}
  • Upset Customer: ${stats.handoffs_angry || 0}

*Response Time*
⏱ Avg Response: ${avgResponseSec}s

*Coverage*
📆 Days with activity: ${stats.days_with_data || 0}`;

return {
  json: {
    ...context,
    statsMessage: message
  }
};

// Format pending handoffs list
const context = $('Merge Context').item.json;
const handoffs = $input.all();

if (!handoffs || handoffs.length === 0 || !handoffs[0].json.id) {
  return {
    json: {
      ...context,
      pendingMessage: `✅ *No Pending Handoffs*\n\n🏨 ${context.hotelName}\n\nAll conversations are being handled. Great job! 👏`
    }
  };
}

let handoffList = handoffs.map((h, i) => {
  const data = h.json;
  const time = new Date(data.created_at).toLocaleString();
  const lang = data.customer_language?.toUpperCase() || '??';
  const conf = data.confidence_score ? (data.confidence_score * 100).toFixed(0) + '%' : 'N/A';

  return `*${i + 1}. ${data.source_type === 'whatsapp' ? '💬' : '📞'} ${data.customer_phone}*
   🌐 ${lang} | 🎯 ${data.intent || 'unknown'} | 📊 ${conf}
   ⚠️ Reason: ${data.reason}
   💬 "${data.summary || 'No summary'}..."
   ⏰ ${time}`;
}).join('\n\n');

const message = `🚨 *Pending Handoffs*\n\n🏨 ${context.hotelName}\n📋 ${handoffs.length} pending request(s)\n\n${handoffList}`;

return {
  json: {
    ...context,
    pendingMessage: message
  }
};
